import { groq, PortableText, stegaClean } from 'next-sanity';
import { Suspense } from 'react';
import { Section } from '@/components/ui/section';
import { cn } from '@/lib/utils';
import { fetchSanityLive } from '@/sanity/lib/fetch';
import FilterList from '@/ui/modules/blog/LatestArticles/FilterList';
import Pretitle from '@/ui/Pretitle';
import PostPreview from '../PostPreview';
import List from './List';

export default async function LatestArticles({
  pretitle,
  intro,
  layout,
  limit,
  showFeaturedPostsFirst,
  displayFilters,
  filteredCategory,
  posts: postsProp,
}: Partial<{
  pretitle: string;
  intro: any;
  layout: 'grid' | 'carousel';
  limit: number;
  showFeaturedPostsFirst: boolean;
  displayFilters: boolean;
  filteredCategory: Sanity.BlogCategory;
  posts?: Sanity.BlogPost[];
}>) {
  const posts =
    postsProp ||
    (await fetchSanityLive<Sanity.BlogPost[]>({
      query: groq`
			*[
				_type == 'blog.post'
				${filteredCategory ? '&& $filteredCategory in categories[]->._id' : ''}
			]|order(
				${showFeaturedPostsFirst ? 'featured desc, ' : ''}
				publishDate desc
			)
			${limit ? `[0...${limit}]` : ''}
			{
				...,
				categories[]->,
				authors[]->
			}
		`,
      params: {
        filteredCategory: filteredCategory?._id || '',
        limit: limit ?? 0,
      },
    }));

  const listClassName = cn(
    'items-stretch gap-x-8 gap-y-12',
    stegaClean(layout) === 'grid'
      ? 'grid md:grid-cols-[repeat(auto-fill,minmax(300px,1fr))]'
      : 'carousel max-xl:full-bleed md:overflow-fade-r pb-4 [--size:320px] max-xl:px-4'
  );

  const sizes =
    stegaClean(layout) === 'grid'
      ? '(min-width: 1024px) 33vw, (min-width: 768px) 50vw, 100vw'
      : '320px';

  return (
    <Section className="space-y-8">
      {intro && (
        <header className="richtext">
          <Pretitle>{pretitle}</Pretitle>
          <PortableText value={intro} />
        </header>
      )}

      {displayFilters && !filteredCategory && <FilterList />}

      <Suspense
        fallback={
          <ul className={listClassName}>
            {Array.from({ length: limit ?? 6 }).map((_, i) => (
              <li key={`skeleton-${i}`}>
                <PostPreview skeleton />
              </li>
            ))}
          </ul>
        }
      >
        <List posts={posts} className={listClassName} sizes={sizes} />
      </Suspense>
    </Section>
  );
}
